      "rank": 1,
      "ballot_id": "B049",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed precision measurement, reaching reproducible 10^-18-level performance and enabling broadly important tests and applications.",
        "attribution": "Katori supplied the decisive magic-wavelength lattice-clock concept and Ye led independent experimental realization and exceptional clock performance.",
        "maturity": "The method has been independently reproduced, continuously improved, and has become a leading international time and frequency platform.",
        "uncertainties": [
          "The eventual division between fundamental-physics discovery and advanced metrology may affect prize framing."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Alfred Y. Cho",
        "Federico Capasso",
        "Jérôme Faist"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum cascade laser created a fundamentally new semiconductor-laser architecture and an exceptionally consequential source for infrared and terahertz spectroscopy.",
        "attribution": "Cho's heterostructure technology, Capasso's quantum-engineering vision, and Faist's landmark realization form a coherent and limited attribution.",
        "maturity": "Three decades of practical devices, spectroscopy, sensing, and industrial use establish both robustness and impact.",
        "uncertainties": [
          "The relative credit for enabling epitaxy versus the invention itself requires careful historical delimitation."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped ions gave quantum information a remarkably clean physical architecture, with high-fidelity control and major advances in computation and simulation.",
        "attribution": "Cirac and Zoller developed seminal trapped-ion quantum-computing proposals, while Blatt provided decisive, sustained experimental realization.",
        "maturity": "The platform has progressed from demonstrations to large programmable systems and precision many-body experiments.",
        "uncertainties": [
          "Credit overlaps with the wider development of trapped-ion quantum control and competing quantum-computing platforms."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B030",
      "proposed_laureates": [
        "Christian J. Bordé",
        "Mark A. Kasevich"
      ],
      "assessment": {
        "nobel_worthiness": "Atom interferometry opened a powerful new class of quantum measurements, combining coherent matter-wave control with exceptional inertial sensitivity.",
        "attribution": "Bordé made foundational contributions to atom-interferometric methods, and Kasevich established influential light-pulse interferometric experiments and sensing applications.",
        "maturity": "Its principles are deeply established and the technique supports mature gravimetry, navigation, and fundamental-test programs.",
        "uncertainties": [
          "The field has many essential contributors, making a three-person attribution intrinsically difficult."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B048",
      "proposed_laureates": [
        "Fedor Jelezko",
        "Jörg Wrachtrup",
        "Mikhail D. Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Coherent optical control of individual solid-state spins made quantum sensing tangible, enabling nanoscale magnetic and other measurements under accessible conditions.",
        "attribution": "Jelezko and Wrachtrup established seminal NV-centre single-spin control, while Lukin made major foundational contributions to optical solid-state spin physics.",
        "maturity": "The experimental phenomena are highly reproducible and now underpin a large quantum-sensing and quantum-network research community.",
        "uncertainties": [
          "The boundary between credit for NV sensing and for the broader solid-state spin-qubit field is not sharp."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B024",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "John D. Joannopoulos",
        "Sajeev John"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic band-gap physics supplied a durable new way to control light, spontaneous emission, and optical confinement through structured dielectric media.",
        "attribution": "Yablonovitch and John introduced central photonic-band-gap ideas, and Joannopoulos made foundational theoretical and computational contributions.",
        "maturity": "The field has decades of experimental confirmation and has enabled resonators, waveguides, emitters, and integrated photonics.",
        "uncertainties": [
          "Applications are diverse, but the most decisive experimental realization and credit boundaries require careful assessment."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B026",
      "proposed_laureates": [
        "Peter F. Moulton",
        "Ursula Keller",
        "Wilson Sibbett"
      ],
      "assessment": {
        "nobel_worthiness": "Titanium-sapphire and practical passive mode locking made reliable femtosecond laser pulses widely available, changing spectroscopy and ultrafast science.",
        "attribution": "Moulton's Ti:sapphire work and Keller's and Sibbett's influential passive-mode-locking advances provide a plausible compact attribution.",
        "maturity": "The techniques have been extensively replicated and remain central to high-performance ultrafast laser systems.",
        "uncertainties": [
          "The candidate combines several interdependent laser advances with a broad community of contributors."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B020",
      "proposed_laureates": [
        "Hoi-Kwong Lo",
        "Jian-Wei Pan"
      ],
      "assessment": {
        "nobel_worthiness": "Decoy-state protocols and satellite entanglement experiments moved quantum communication from conceptually secure schemes toward demonstrated long-distance networks.",
        "attribution": "Lo made the key decoy-state contribution, and Pan led landmark satellite-based distribution, teleportation, and entanglement experiments.",
        "maturity": "The security ideas and experimental links have been independently tested, though full global deployment remains incomplete.",
        "uncertainties": [
          "The achievement overlaps historically with the broader founding of quantum cryptography and with numerous network contributors."
        ]
      }
    }
  ]
